export { createCustomClient } from "jsr:@brad-jones/deno-net-open-api-client@0.2.4";

/**
 * Create a client with all available operations.
 * This is convenient but will include all operations in your bundle.
 * For better tree-shaking, use createCustomClient() to select specific operations.
 */
export function createClient(config: OpenAPIClientConfig) {
  return createCustomClient(config, {
    invoicesList,
    invoicesCreate,
    invoicesSend,
    invoicesRemind,
    invoicesCancel,
    invoicesPayments,
    invoicesPaymentsDelete,
    invoicesRefunds,
    invoicesRefundsDelete,
    invoicesGenerateQrCode,
    invoicingGenerateNextInvoiceNumber,
    invoicesGet,
    invoicesUpdate,
    invoicesDelete,
    invoicesSearchInvoices,
    templatesList,
    templatesCreate,
    templatesGet,
    templatesUpdate,
    templatesDelete,
    connectionsGet,
    invoiceConnectionDetailsGet,
  });
}
